//! The raw stream of a request a capture is watching: every SSE `data:` payload, verbatim
//! and in arrival order, before any parsing (card fb6d7912).
//!
//! A captured response records what the adapter PARSED (`TextGenerationResponse`), which
//! cannot say whether a wrong tool call was generated by the model or produced by the parse
//! that split one stream into reasoning, content and tool calls. On 2026-10-12 a citizen's
//! first call of several turns executed as `work/create` titled "x" while her reasoning in the
//! SAME response planned another call, and no record anywhere held the tokens that would
//! settle it (Astra and Kimi swept the trace, the prompt captures and both logs).
//!
//! Only the capture owner arms a tap, and only for a call it is recording, so a request no
//! capture watches costs one map lookup at stream start and nothing per token. The payloads
//! live from the stream until the capture records its terminal entry, which takes them.

use std::collections::HashMap;
use std::sync::LazyLock;

use parking_lot::Mutex;

/// Armed request ids. `None` = armed, nothing streamed yet; `Some` = the payloads so far.
static TAPS: LazyLock<Mutex<HashMap<String, Option<Vec<String>>>>> =
    LazyLock::new(Default::default);

/// Watch `request_id`'s stream: the capture owner calls this before dispatch.
pub fn arm(request_id: &str) {
    TAPS.lock().entry(request_id.to_owned()).or_insert(None);
}

/// The payloads `request_id` streamed, ending the watch. `None` when it was never armed or
/// streamed nothing. The capture owner calls this when it records the call's end, on every
/// path (completed, failed, cancelled), so no armed entry outlives its call.
pub fn take(request_id: &str) -> Option<Vec<String>> {
    TAPS.lock().remove(request_id).flatten()
}

/// The stream parser's side: collects payloads locally (no lock per token) and deposits
/// them when the stream ends, including on an error return, so a failed stream is recorded
/// too. A stream retried under the same request id appends.
pub(crate) struct WireTap {
    request_id: Option<String>,
    payloads: Vec<String>,
}

impl WireTap {
    pub(crate) fn open(request_id: Option<&str>) -> Self {
        let request_id = request_id
            .filter(|id| TAPS.lock().contains_key(*id))
            .map(str::to_owned);
        Self {
            request_id,
            payloads: Vec::new(),
        }
    }

    pub(crate) fn push(&mut self, payload: &str) {
        if self.request_id.is_some() {
            self.payloads.push(payload.to_owned());
        }
    }
}

impl Drop for WireTap {
    fn drop(&mut self) {
        let Some(id) = self.request_id.take() else {
            return;
        };
        // Deposited only while the call is still armed: a capture that already ended
        // took its entry, and nothing is resurrected after it.
        if let Some(slot) = TAPS.lock().get_mut(&id) {
            slot.get_or_insert_with(Vec::new)
                .extend(std::mem::take(&mut self.payloads));
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // what this catches: a captured call whose raw stream is lost, or a watched entry that
    // outlives its call. An armed request keeps every payload in order, including across a
    // retried stream; an unarmed one keeps nothing; take ends the watch, so a late deposit
    // never resurrects it.
    #[test]
    fn an_armed_request_keeps_its_raw_stream_until_taken() {
        let id = format!("wire-test-{}", uuid::Uuid::new_v4());
        let mut unwatched = WireTap::open(Some(&id));
        unwatched.push("{\"ignored\":true}");
        drop(unwatched);
        assert_eq!(take(&id), None, "nothing is kept for a request no capture armed");

        arm(&id);
        let mut first = WireTap::open(Some(&id));
        first.push("{\"choices\":[{\"delta\":{\"reasoning_content\":\"plan\"}}]}");
        first.push("{\"choices\":[{\"delta\":{\"tool_calls\":[{\"index\":0}]}}]}");
        drop(first);
        let mut retry = WireTap::open(Some(&id));
        retry.push("[DONE]");
        drop(retry);
        let wire = take(&id).expect("the armed stream was kept");
        assert_eq!(wire.len(), 3);
        assert!(wire[0].contains("reasoning_content") && wire[2] == "[DONE]", "in arrival order");

        let mut late = WireTap::open(Some(&id));
        late.push("after the capture ended");
        drop(late);
        assert_eq!(take(&id), None, "a taken watch is not resurrected");
        assert_eq!(WireTap::open(None).request_id, None);
    }
}
